PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE productos (   id INTEGER PRIMARY KEY AUTOINCREMENT,   producto TEXT NOT NULL UNIQUE COLLATE NOCASE,   precio REAL NOT NULL DEFAULT 0,   categoria TEXT DEFAULT '',   stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),   disponible TEXT NOT NULL DEFAULT 'si',   vendidos INTEGER NOT NULL DEFAULT 0,   fecha TEXT,   stock_colores TEXT DEFAULT '',   stock_variantes TEXT DEFAULT '',   extra TEXT DEFAULT '{}' );
CREATE TABLE ordenes (   id_orden TEXT PRIMARY KEY,   numero_orden INTEGER NOT NULL UNIQUE,   fecha TEXT NOT NULL,   estado TEXT NOT NULL DEFAULT 'pendiente',   metodo_pago TEXT,   referencia TEXT,   telefono_pago TEXT,   correo_cliente TEXT,   comprobante_url TEXT,   motivo TEXT,   fecha_rechazo TEXT,   total REAL NOT NULL DEFAULT 0 );
CREATE TABLE orden_items (   id INTEGER PRIMARY KEY AUTOINCREMENT,   id_orden TEXT NOT NULL REFERENCES ordenes(id_orden) ON DELETE CASCADE,   producto TEXT NOT NULL,   color TEXT DEFAULT '',   talla TEXT DEFAULT '',   cantidad INTEGER NOT NULL CHECK (cantidad > 0),   precio_unit REAL NOT NULL,   categoria TEXT DEFAULT '' );
CREATE TABLE ventas (   id INTEGER PRIMARY KEY AUTOINCREMENT,   fecha TEXT NOT NULL,   producto TEXT,   categoria TEXT,   precio REAL NOT NULL DEFAULT 0,   correo_cliente TEXT,   canal TEXT,   precio_bs REAL,   tasa_bs REAL,   nota TEXT,   metodo_pago TEXT );
CREATE TABLE fiados (   id TEXT PRIMARY KEY,   fecha TEXT NOT NULL,   cliente TEXT,   producto TEXT,   precio REAL,   precio_bs REAL,   tasa_bs REAL,   fecha_pago TEXT,   estado_pago TEXT NOT NULL DEFAULT 'pendiente',   nota TEXT,   correo TEXT );
CREATE TABLE gastos (   id TEXT PRIMARY KEY,   fecha TEXT NOT NULL,   concepto TEXT,   monto REAL NOT NULL,   categoria TEXT,   nota TEXT );
CREATE TABLE cashea (   id TEXT PRIMARY KEY,   fecha TEXT NOT NULL,   cliente TEXT,   producto TEXT,   total REAL,   inicial REAL,   financiado REAL,   cuotas INTEGER,   cuota_sugerida REAL,   cobros INTEGER NOT NULL DEFAULT 0,   cobrado_usd REAL NOT NULL DEFAULT 0,   saldo REAL NOT NULL,   proximo_cobro TEXT,   estado TEXT NOT NULL DEFAULT 'activo',   nota TEXT,   correo TEXT );
CREATE TABLE cierre_semanal (   semana TEXT PRIMARY KEY,   desde TEXT,   hasta TEXT,   prendas INTEGER,   total_bs REAL,   total_usd REAL,   actualizado TEXT );
CREATE TABLE config (   clave TEXT PRIMARY KEY,   valor TEXT );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_ordenes_estado_fecha ON ordenes(estado, fecha DESC);
CREATE INDEX idx_ordenes_correo ON ordenes(correo_cliente);
CREATE INDEX idx_items_orden ON orden_items(id_orden);
CREATE INDEX idx_ventas_fecha ON ventas(fecha DESC);
CREATE INDEX idx_ventas_correo ON ventas(correo_cliente);
CREATE INDEX idx_fiados_estado ON fiados(estado_pago, fecha DESC);
CREATE INDEX idx_gastos_fecha ON gastos(fecha DESC);
CREATE INDEX idx_cashea_estado ON cashea(estado, proximo_cobro);
